function drawHydreigonThreeHeadedDragon(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.3;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.5;

  const leftHeadLag  = Math.sin(t * 2.5 - 0.6) * 3.5;
  const rightHeadLag = Math.sin(t * 2.5 + 0.6) * 3.5;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 44, 28 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. 6 Cánh đen
  ctx.fillStyle = '#1e293b';
  // Trái
  ctx.beginPath(); ctx.moveTo(-10, by + 4); ctx.lineTo(-36, by - 16); ctx.lineTo(-18, by + 16); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-12, by + 6); ctx.lineTo(-38, by);      ctx.lineTo(-20, by + 18); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-14, by + 8); ctx.lineTo(-34, by + 14); ctx.lineTo(-22, by + 20); ctx.fill();
  // Phải
  ctx.beginPath(); ctx.moveTo(10,  by + 4); ctx.lineTo(36,  by - 16); ctx.lineTo(18,  by + 16); ctx.fill();
  ctx.beginPath(); ctx.moveTo(12,  by + 6); ctx.lineTo(38,  by);      ctx.lineTo(20,  by + 18); ctx.fill();
  ctx.beginPath(); ctx.moveTo(14,  by + 8); ctx.lineTo(34,  by + 14); ctx.lineTo(22,  by + 20); ctx.fill();

  // 3. Đuôi
  ctx.beginPath(); ctx.roundRect(-4, by + 22, 8, 18, 3); ctx.fill();
  ctx.fillStyle = '#e11d48';
  ctx.fillRect(-3, by + 26, 6, 3);
  ctx.fillRect(-3, by + 32, 6, 3);

  // 4. Thân & Sọc
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, by + 12, 18 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#e11d48';
  ctx.beginPath(); ctx.roundRect(-8, by + 8,  16, 4, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-6, by + 14, 12, 4, 2); ctx.fill();

  // 5. Cổ & Đầu chính
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.roundRect(-5, by - 4, 10, 14, 3); ctx.fill();
  ctx.fillStyle = '#e11d48';
  ctx.beginPath(); ctx.arc(0, by - 12, 14, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.arc(0, by - 12, 9, 0, Math.PI * 2); ctx.fill();

  if (!blink) {
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.arc(-3, by - 13, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(3,  by - 13, 2, 0, Math.PI * 2); ctx.fill();
  }

  // 6. Đầu tay trái
  const lhx = -22;
  const lhy = by + 2 + leftHeadLag;
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.roundRect(-16, by + 4, 10, 8, 2); ctx.fill();
  ctx.fillStyle = '#e11d48';
  ctx.beginPath(); ctx.arc(lhx, lhy, 8, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.arc(lhx, lhy, 6, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.arc(lhx - 2, lhy + 2, 3, 0, Math.PI * 2); ctx.fill();

  // 7. Đầu tay phải
  const rhx = 22;
  const rhy = by + 2 + rightHeadLag;
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.roundRect(6, by + 4, 10, 8, 2); ctx.fill();
  ctx.fillStyle = '#e11d48';
  ctx.beginPath(); ctx.arc(rhx, rhy, 8, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1d4ed8';
  ctx.beginPath(); ctx.arc(rhx, rhy, 6, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.arc(rhx + 2, rhy + 2, 3, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
